import{_ as o,o as t,c as r,a1 as a}from"./chunks/framework.C5u0ZYB0.js";const i="/projects/aquilifer/screenshots/providers-empty.png",n="/projects/aquilifer/screenshots/providers-form.png",s="/projects/aquilifer/screenshots/providers-added.png",g=JSON.parse('{"title":"Providers","description":"","frontmatter":{},"headers":[],"relativePath":"docs/providers.md","filePath":"docs/providers.md","lastUpdated":1789939732000}'),d={name:"docs/providers.md"};function p(l,e,c,h,f,u){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="providers" tabindex="-1">Providers <a class="header-anchor" href="#providers" aria-label="Permalink to &quot;Providers&quot;">​</a></h1><p>A provider is a connection between Aquilifer and one LLM backend, using your own credential. You add providers from the extension&#39;s settings page (click the Aquilifer icon → <strong>Options</strong>, or right-click the icon → <strong>Options</strong>), before any website can use them.</p><h2 id="two-kinds-of-provider" tabindex="-1">Two kinds of provider <a class="header-anchor" href="#two-kinds-of-provider" aria-label="Permalink to &quot;Two kinds of provider&quot;">​</a></h2><p><strong>Anthropic</strong>: Claude, using your own Anthropic API key.</p><p><strong>OpenAI-compatible</strong>: anything that speaks OpenAI&#39;s chat-completions format: OpenAI itself, or a self-hosted/local backend such as <a href="https://github.com/ggml-org/llama.cpp" target="_blank" rel="noreferrer">llama.cpp</a>, <a href="https://ollama.com/" target="_blank" rel="noreferrer">Ollama</a>, or <a href="https://lmstudio.ai/" target="_blank" rel="noreferrer">LM Studio</a>. You provide a base URL (e.g. <code>http://localhost:8080</code>); the API key is optional, since many local backends don&#39;t require one.</p><h2 id="adding-a-provider" tabindex="-1">Adding a provider <a class="header-anchor" href="#adding-a-provider" aria-label="Permalink to &quot;Adding a provider&quot;">​</a></h2><p>You don&#39;t pick a model when adding a provider; just connect it, and choose the model afterward.</p><p><img src="'+i+'" alt="The Providers tab with no providers configured yet, and the empty Add provider form below it"></p><ol><li><p>Fill in a label (just for your own reference, sites never see it) and the credential (API key for Anthropic; base URL, and optionally an API key, for OpenAI-compatible).</p><p><img src="'+n+'" alt="The Add provider form filled in with a label and a masked API key"></p></li><li><p>Click <strong>Connect</strong>. Aquilifer asks the provider itself which models are available; this both discovers what you can use and proves the credential/URL actually work, with no separate test request needed. The first model returned is picked automatically; you can change it any time afterward from <a href="/projects/aquilifer/docs/popup">the toolbar popup</a>.</p></li><li><p>If the provider doesn&#39;t support listing its own models (some self-hosted backends don&#39;t), Aquilifer asks you to type a model ID manually instead, then verifies it with one real request before saving.</p></li></ol><p><img src="'+s+'" alt="The Providers tab after connecting, showing the new provider marked as the default with its auto-picked model"></p><p>For a self-hosted/local backend, connecting it the first time will also ask your browser for permission to make requests to that URL. This is a one-time browser permission prompt, separate from Aquilifer&#39;s own connect-a-site approval.</p><h2 id="default-provider-and-switching" tabindex="-1">Default provider and switching <a class="header-anchor" href="#default-provider-and-switching" aria-label="Permalink to &quot;Default provider and switching&quot;">​</a></h2><p>The first provider you add becomes the default automatically. When a site connects for the first time, the approval popup lets you pick which provider to bind it to. You can change the default at any time, from the same settings page, or with one click from <a href="/projects/aquilifer/docs/popup">the toolbar popup</a>.</p><p><strong>Aquilifer binds exactly one provider to each site at a time.</strong> If a site later needs a different type of provider than the one it&#39;s already bound to (for example, it wants to call Anthropic natively but you&#39;re bound to a self-hosted model), Aquilifer prompts you to <strong>switch</strong>, replacing the binding, not adding a second one. You can approve or deny that switch; denying it leaves the existing binding untouched.</p><h2 id="removing-a-provider" tabindex="-1">Removing a provider <a class="header-anchor" href="#removing-a-provider" aria-label="Permalink to &quot;Removing a provider&quot;">​</a></h2><p>Delete it from the same settings page. Any site currently bound to it will show <code>provider_unavailable</code> errors, or trigger a fresh connect/switch prompt, depending on what it asks for next.</p>',16)])])}const v=o(d,[["render",p]]);export{g as __pageData,v as default};
